(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[166],{1504:function(t,e,n){"use strict";n.r(e),e.default={code:"B3-01",title:"K07 清單讀取與索引走訪",tier:"t1",unlockCode:"B3-01-ListTraversal",tasks:[{id:"JSA01-D01",code:"B3-01-JSA01-D01",title:"清單逐一讀取",description:"第一行輸入一個整數 N，第二行輸入 N 個整數。請依照原本順序逐一輸出每個數字，每個數字各佔一行。本題用來示範清單逐一讀取與輸出。",examples:[{input:"3\n5 8 2",output:"5\n8\n2",explanation:"依序輸出清單中的三個數字。"},{input:"2\n10 20",output:"10\n20",explanation:"依序輸出 10 與 20。"}],testCases:[{input:"1\n7",expectedOutput:"7",score:20},{input:"3\n5 8 2",expectedOutput:"5\n8\n2",score:20},{input:"4\n1 2 3 4",expectedOutput:"1\n2\n3\n4",score:20},{input:"5\n9 7 5 3 1",expectedOutput:"9\n7\n5\n3\n1",score:20},{input:"2\n100 200",expectedOutput:"100\n200",score:20}],difficulty:"L1",difficultyLabel:"L1｜基礎",sb3Path:"m0/B3-01-ListTraversal/JSA01-D01.sb3"},{id:"IDX01-001",code:"B3-01-IDX01-001",title:"指定位置的數字",description:"給定 N 個整數與一個位置 P，請輸出第 P 個數字。位置從 1 開始計算。",examples:[{input:"5\n8 3 12 7 10\n3",output:"12",explanation:"第 3 個數字是 12。"}],testCases:[{input:"5\n8 3 12 7 10\n3",expectedOutput:"12",score:10},{input:"4\n1 2 3 4\n1",expectedOutput:"1",score:10},{input:"4\n1 2 3 4\n4",expectedOutput:"4",score:10},{input:"6\n-1 -2 -3 -4 -5 -6\n5",expectedOutput:"-5",score:10}],difficulty:"L1",difficultyLabel:"L1｜基礎",sb3Path:"m0/B3-01-ListTraversal/IDX01-001.sb3"},{id:"count-018",code:"B3-01-count-018",title:"冒險日誌",description:"勇者寫了 N 天的冒險日誌，清單中依序記錄了每天打倒的怪物數量。\n例如清單的第一個數字是第 1 天打倒的數量，第二個數字是第 2 天的...\n請你格式化輸出每天的戰績，格式為：Day-[第幾天]-[數量]。\n輸入格式\n輸入共有兩行。第一行是一個整數 N，代表天數。\n第二行輸入 N 個整數，代表每天怪物的數量。\n程式依序輸出 N 天資料，每天格式為 Day-i-數量 不同天中間以空白間隔。",examples:[{input:"2\n15 5",output:"Day-1-15 Day-2-5",explanation:"第一行輸入數字2，代表有2天資料\n第二行有2筆整數資料，15 5\n程式依序輸出所有天數資料：Day-1-15 Day-2-5"},{input:"3\n12 15 20",output:"Day-1-12 Day-2-15 Day-3-20",explanation:"第一行輸入數字3，代表有3天資料\n第二行有3筆整數資料，12 15 20\n程式依序輸出所有天數資料：Day-1-12 Day-2-15 Day-3-20"}],testCases:[{input:"1\n100",expectedOutput:"Day-1-100",score:10},{input:"4\n7 7 9 7",expectedOutput:"Day-1-7 Day-2-7 Day-3-9 Day-4-7",score:10},{input:"4\n33 22 44 11",expectedOutput:"Day-1-33 Day-2-22 Day-3-44 Day-4-11",score:10},{input:"3\n25 2 3",expectedOutput:"Day-1-25 Day-2-2 Day-3-3",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/B3-01-ListTraversal/count-018.sb3"},{id:"count-017",code:"B3-01-count-017",title:"倒轉時光",description:"勇者獲得了一個「時光倒流」的魔法卷軸。這個卷軸上有一串數字密碼，但是必須從最後一個數字讀回到第一個數字，魔法才能生效。 請讀取一個清單，並將清單內的數字「由後往前」印出來。\n輸入格式\n輸入共有兩行。第一行是一個整數 N，代表密碼長度。\n第二行輸入 N 個整數，代表N個數字的密碼組合。\n程式反序輸 N 筆密碼數字資料，中間以空白間隔\n(提示：循環計數迴圈起點設為清單長度，終點設為 1，間隔設為 -1)",examples:[{input:"4\n10 20 30 40",output:"40 30 20 10",explanation:"第一行輸入數字4，代表密碼有4筆資料\n第二行有4筆整數資料，10 20 30 40\n程式反敘輸出密碼資料：40 30 20 10"},{input:"3\n1 2 3",output:"3 2 1",explanation:"第一行輸入數字3，代表密碼有3筆資料\n第二行有3筆整數資料，1 2 3\n程式反敘輸出密碼資料：3 2 1"}],testCases:[{input:"2\n100 20",expectedOutput:"20 100",score:10},{input:"4\n7 7 9 7",expectedOutput:"7 9 7 7",score:10},{input:"5\n1 2 3 4 5",expectedOutput:"5 4 3 2 1",score:10},{input:"4\n0 1 0 1",expectedOutput:"1 0 1 0",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/B3-01-ListTraversal/count-017.sb3"},{id:"IDX01-007",code:"B3-01-IDX01-007",title:"左右鄰居總和",description:"給定 N 個整數與位置 P，請計算第 P 個數字左右鄰居的總和。若沒有左鄰居或右鄰居，該側視為 0。",examples:[{input:"5\n10 20 30 40 50\n3",output:"60",explanation:"第 3 個數字的左鄰居是 20，右鄰居是 40，總和為 60。"}],testCases:[{input:"5\n10 20 30 40 50\n3",expectedOutput:"60",score:10},{input:"5\n10 20 30 40 50\n1",expectedOutput:"20",score:10},{input:"5\n10 20 30 40 50\n5",expectedOutput:"40",score:10},{input:"1\n99\n1",expectedOutput:"0",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/B3-01-ListTraversal/IDX01-007.sb3"}]}}}]);